architectureDiagramMermaid:
flowchart TD
    Cron["⏰ Crontab macOS (0 8-23 * * *)"] --> BackupAll["🐚 scripts/backup_all.sh"]
    BackupAll --> CheckDaily{"📅 Existe backup hoje?"}
    CheckDaily -- Sim --> Skip["⚡ Pula Projeto (Economiza banda)"]
    CheckDaily -- Não --> CheckTCP{"🔌 Netcat (nc) TCP OK?"}
    CheckTCP -- Falha --> LogError["⚠️ Log de Erro / Próximo ciclo"]
    CheckTCP -- OK --> PgDump["🐘 Executa pg_dump"]
    PgDump --> CheckDump{"💾 Dump Concluído?"}
    CheckDump -- OK --> SuccessClean["✅ Limpa > RETENTION_DAYS e Notifica"]
    CheckDump -- Erro --> Rollback["🗑️ Auto-Limpeza / Deleta .sql parcial"]
